param([Parameter(Mandatory)][string]$Sentinel, [string]$Dist)
$ErrorActionPreference = 'Stop'
$repo=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..')); $temp=[IO.Path]::GetFullPath([IO.Path]::GetTempPath()); if(-not $Dist){$Dist=Join-Path $repo 'apps\dim-sum-atlas\dist\squirrel-windows'}; $resolvedDist=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $Dist).Path); $resolvedSentinel=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $Sentinel).Path); if(-not ($resolvedDist.StartsWith($repo,[StringComparison]::OrdinalIgnoreCase) -or $resolvedDist.StartsWith($temp,[StringComparison]::OrdinalIgnoreCase))){throw 'Installer dist escapes the repository or temp containment roots.'}; if([IO.Path]::GetFileName($resolvedDist) -ne 'squirrel-windows'){throw 'Installer dist must be the exact squirrel-windows directory.'}; if(-not ($resolvedSentinel.StartsWith($repo,[StringComparison]::OrdinalIgnoreCase) -or $resolvedSentinel.StartsWith($temp,[StringComparison]::OrdinalIgnoreCase))){throw 'Build sentinel escapes the repository or temp containment roots.'}; $start = (Get-Item -LiteralPath $resolvedSentinel).LastWriteTimeUtc
$files = @((Get-ChildItem -LiteralPath $resolvedDist -Filter 'Dim-Sum-Atlas-*.exe' | Select-Object -First 1), (Get-Item -LiteralPath (Join-Path $resolvedDist 'RELEASES')), (Get-ChildItem -LiteralPath $resolvedDist -Filter '*-full.nupkg' | Select-Object -First 1), (Get-Item -LiteralPath (Join-Path $resolvedDist 'installer-manifest.json')))
$stale = @($files | Where-Object { $_.LastWriteTimeUtc -le $start }); if ($files.Count -ne 4 -or $stale.Count -gt 0) { throw 'Squirrel output is missing or not newer than the build sentinel.' }
Write-Output 'PASS fresh Squirrel output'
